function autoAdvanceReadyMatches(){
  // Heal stale/legacy rooms first: a championship final that was preassigned
  // before the bronze gate existed must be released as long as no real play
  // data has been entered yet.
  const blockedFinals=state.matches.filter(m=>singleElimBronzeBeforeFinalBlocked(m,state.matches,state.meta)&&!matchHasDecisionData(m));
  blockedFinals.forEach(m=>{
    if(m.status==="ready"||m.status==="in_progress"){m.status="pending";m.startedAt=null;m.updatedAt=Date.now();}
  });
  if(blockedFinals.length) clearCourtAssignmentRefs(state,blockedFinals.map(m=>m.id));

  const blockedDouble=(state.meta&&state.meta.formatType==="double"&&window.BXHDoubleElim)
    ? state.matches.filter(m=>!m.completed&&!m.isBye&&m.status==="ready"&&!matchHasDecisionData(m)&&!window.BXHDoubleElim.isPhaseOpen(state.matches,m))
    : [];
  blockedDouble.forEach(m=>{m.status="pending";m.startedAt=null;m.updatedAt=Date.now();});
  if(blockedDouble.length) clearCourtAssignmentRefs(state,blockedDouble.map(m=>m.id));

  const readyStations = new Set();
  state.matches.forEach(m=>{ if(!m.isBye && m.status==="ready" && m.station!=null) readyStations.add(m.station); });

  const candidates = state.matches.filter(m=>
    !m.isBye &&
    m.status==="pending" &&
    !m.completed &&
    m.a && m.b &&
    m.station!=null &&
    !readyStations.has(m.station) &&
    !singleElimBronzeBeforeFinalBlocked(m,state.matches,state.meta) &&
    (!(state.meta&&state.meta.formatType==="double") || !window.BXHDoubleElim || window.BXHDoubleElim.isPhaseOpen(state.matches,m))
  );

  candidates.sort((a,b)=>{
    if((a.round||0)!==(b.round||0)) return (a.round||0)-(b.round||0);
    return (a.indexInRound||0)-(b.indexInRound||0);
  });

  const claimed = new Set();
  candidates.forEach(m=>{
    if(claimed.has(m.station)) return;
    m.status = "ready";
    m.updatedAt = Date.now();
    claimed.add(m.station);
  });
}

function canCourtSwapSource(m){
  return !!(m&&!m.isBye&&!m.completed&&m.a&&m.b&&!m.skippedAt&&!m.callPass&&!matchHasDecisionData(m)&&m.status!=="paused");
}

function canCourtSwapTarget(m,sourceMatch,st=state){
  if(window.BXHCourtRetirement&&(!window.BXHCourtRetirement.accepts(st,m?.station)||!window.BXHCourtRetirement.accepts(st,sourceMatch?.station)))return false;
  if(!m||!sourceMatch||m.id===sourceMatch.id||m.isBye||m.completed||!m.a||!m.b) return false;
  if(singleElimBronzeBeforeFinalBlocked(m,(st&&st.matches)||[],(st&&st.meta)||{})) return false;
  if(m.status==="in_progress"||m.status==="paused"||m.skippedAt||m.callPass||matchHasDecisionData(m)) return false;
  return true;
}

function canManualAssignMatch(m,st=state){return !!(m&&!m.isBye&&!m.completed&&m.a&&m.b&&!matchHasDecisionData(m)&&m.status!=="paused"&&!m.skippedAt&&!m.callPass&&!singleElimBronzeBeforeFinalBlocked(m,(st&&st.matches)||[],(st&&st.meta)||{}));}

function checkWinnerSide(m){
  if(m.scoreA>=4 && m.scoreA>m.scoreB) return "A";
  if(m.scoreB>=4 && m.scoreB>m.scoreA) return "B";
  return null;
}

function clearCourtAssignmentRefs(st,matchIds){
  const ids=new Set(matchIds.filter(Boolean));
  Object.values((st&&st.courtAssignments)||{}).forEach(c=>{if(!c)return;if(ids.has(c.currentMatchId))c.currentMatchId=null;if(ids.has(c.nextMatchId))c.nextMatchId=null;});
}

function computeRoundRobinStandings(st=state){
  const map = {};
  st.players.forEach(p=>{ map[p.id] = { id:p.id, name:p.name, played:0, wins:0, losses:0, scoreFor:0, scoreAgainst:0, diff:0, tied:false, rank:0 }; });
  const h2h = {};
  st.matches.filter(m=>m.bracket==="RR" && m.completed && m.winnerId).forEach(m=>{
    const aId=m.a.playerId, bId=m.b.playerId;
    const loserId = m.winnerId===aId?bId:aId;
    const isQuick = m.resultMethod==="quick_decision";
    if(map[m.winnerId]){ map[m.winnerId].played++; map[m.winnerId].wins++; if(!isQuick){ map[m.winnerId].scoreFor+=(m.winnerId===aId?m.scoreA:m.scoreB); map[m.winnerId].scoreAgainst+=(m.winnerId===aId?m.scoreB:m.scoreA); } }
    if(map[loserId]){ map[loserId].played++; map[loserId].losses++; if(!isQuick){ map[loserId].scoreFor+=(loserId===aId?m.scoreA:m.scoreB); map[loserId].scoreAgainst+=(loserId===aId?m.scoreB:m.scoreA); } }
    h2h[m.winnerId] = h2h[m.winnerId]||{}; h2h[m.winnerId][loserId]='win';
    h2h[loserId] = h2h[loserId]||{}; h2h[loserId][m.winnerId]='loss';
  });
  Object.values(map).forEach(p=>p.diff=p.scoreFor-p.scoreAgainst);
  let list = Object.values(map);
  const sameStats = (a,b)=> a.wins===b.wins && a.diff===b.diff && a.scoreFor===b.scoreFor;
  list.sort((a,b)=>{
    if(b.wins!==a.wins) return b.wins-a.wins;
    if(h2h[a.id] && h2h[a.id][b.id]) return h2h[a.id][b.id]==='win' ? -1 : 1;
    if(b.diff!==a.diff) return b.diff-a.diff;
    if(b.scoreFor!==a.scoreFor) return b.scoreFor-a.scoreFor;
    return 0;
  });
  let i=0;
  while(i<list.length){
    let j=i;
    while(j+1<list.length && sameStats(list[j+1],list[i])) j++;
    if(j>i){
      const group = list.slice(i,j+1);
      group.forEach(p=>{ p.subWins=0; });
      for(let x=0;x<group.length;x++){
        for(let y=0;y<group.length;y++){
          if(x!==y && h2h[group[x].id] && h2h[group[x].id][group[y].id]==='win') group[x].subWins++;
        }
      }
      group.sort((a,b)=>b.subWins-a.subWins);
      for(let x=0;x<group.length;x++) list[i+x]=group[x];
      let gi=i;
      while(gi<=j){
        let gj=gi;
        while(gj+1<=j && list[gj+1].subWins===list[gi].subWins) gj++;
        const tied = gj>gi;
        for(let x=gi;x<=gj;x++){ list[x].tied=tied; list[x].rank=i+1; }
        gi=gj+1;
      }
    } else {
      list[i].tied=false; list[i].rank=i+1;
    }
    i=j+1;
  }
  return list;
}

function correctionProbe(st,matchId){
  const matches=st&&Array.isArray(st.matches)?st.matches:[];
  const target=matches.find(x=>x&&x.id===matchId);
  if(!target) return {ok:false,reason:"not-found"};
  if(!target.completed && target.status!=="completed") return {ok:false,reason:"not-completed"};
  const station=Number(target.station||0);
  const court=st.courtAssignments&&st.courtAssignments[courtKey(station)];
  const activeId=court&&court.currentMatchId;
  if(activeId && activeId!==matchId){
    const active=matches.find(x=>x.id===activeId);
    if(correctionMatchHasActualPlay(active)) return {ok:false,reason:"court-already-started",blockedMatchId:activeId};
  }
  let probe;
  try{ probe=JSON.parse(JSON.stringify(st)); }catch(e){ return {ok:false,reason:"corrupt-data"}; }
  const probeTarget=(probe.matches||[]).find(x=>x.id===matchId);
  if(!probeTarget) return {ok:false,reason:"not-found"};
  probeTarget.completed=false;
  probeTarget.status="in_progress";
  probeTarget.winnerId=null;
  probeTarget.loserId=null;
  probeTarget.resultMethod=null;
  probeTarget.confirmedAt=null;
  probeTarget.completedAt=null;
  probeTarget.hunterData=null;
  if(probe.courtAssignments&&probe.courtAssignments[courtKey(station)]){
    probe.courtAssignments[courtKey(station)].currentMatchId=matchId;
  }
  rebuildPropagationForState(probe);
  const changed=matches.filter(original=>{
    if(!original||original.id===matchId) return false;
    const after=(probe.matches||[]).find(x=>x.id===original.id);
    return after && correctionParticipantSignature(original)!==correctionParticipantSignature(after);
  });
  const blocked=changed.find(correctionMatchHasActualPlay);
  if(blocked) return {ok:false,reason:"downstream-started",blockedMatchId:blocked.id};
  return {ok:true,target,station};
}

function createHunterRoundEvent(match,side,type,points,at){
  const log=Array.isArray(match&&match.log)?match.log:[];
  const seq=log.length+1;
  const ts=Number(at)||Date.now();
  return {
    v:HUNTER_ROUND_SCHEMA_VERSION,
    eventId:String((match&&match.id)||"match")+":r"+seq+":"+ts,
    seq,
    side,
    type,
    points,
    t:ts
  };
}

function ensureMatchScoringFields(m){
  if(!m.scoringMode) m.scoringMode = resolveScoringModeForRound(m.bracket, m.round);
  if(m.resultMethod===undefined) m.resultMethod = m.completed ? "score" : null;
  if(m.confirmedBy===undefined) m.confirmedBy = null;
  if(m.confirmedAt===undefined) m.confirmedAt = null;
  if(!Array.isArray(m.faultActions)) m.faultActions = [];
}

function ensureMatchStatusFields(m){
  if(!m.status) m.status = m.completed ? "completed" : "pending";
  if(m.startedAt===undefined) m.startedAt = null;
  if(m.completedAt===undefined) m.completedAt = null;
  if(m.updatedAt===undefined) m.updatedAt = null;
  if(m.updatedBy===undefined) m.updatedBy = null;
}

function evaluateMatchCompletion(m){
  if(!m) return { ok:false, reason:"not-found" };
  if(m.completed || m.status==="completed") return { ok:false, reason:"already-completed" };
  if(!m.a || !m.b || !m.a.playerId || !m.b.playerId) return { ok:false, reason:"missing-players" };
  const scoreA = Number(m.scoreA), scoreB = Number(m.scoreB);
  if(!Number.isFinite(scoreA) || !Number.isFinite(scoreB) || scoreA<0 || scoreB<0) return { ok:false, reason:"invalid-score" };
  if(scoreA===scoreB) return { ok:false, reason:"tie" };
  const hunterLedger=validateHunterRoundLedger(m);
  if(!hunterLedger.ok) return { ok:false, reason:"round-ledger-mismatch" };
  // Authoritative winner is ALWAYS recomputed here from the current live score, never
  // trusted from any UI selection state, click target, or caller-supplied value.
  const winnerSide = checkWinnerSide(m);
  if(!winnerSide) return { ok:false, reason:"no-winner" };
  const winnerId = winnerSide==="A" ? m.a.playerId : m.b.playerId;
  const loserId = winnerSide==="A" ? m.b.playerId : m.a.playerId;
  if(!winnerId || !loserId) return { ok:false, reason:"missing-players" };
  return { ok:true, winnerSide, winnerId, loserId };
}

function evaluateQuickDecision(m, selectedWinnerId){
  if(!m) return { ok:false, reason:"not-found" };
  if(m.completed || m.status==="completed" || m.winnerId) return { ok:false, reason:"already-completed" };
  if(!m.a || !m.b || !m.a.playerId || !m.b.playerId) return { ok:false, reason:"missing-players" };
  if(!selectedWinnerId) return { ok:false, reason:"no-selection" };
  if(selectedWinnerId!==m.a.playerId && selectedWinnerId!==m.b.playerId) return { ok:false, reason:"invalid-selection" };
  const loserId = selectedWinnerId===m.a.playerId ? m.b.playerId : m.a.playerId;
  return { ok:true, winnerId:selectedWinnerId, loserId };
}

function getMatch(id){ return state.matches.find(m=>m.id===id); }

function idleCourtCandidates(st,stationNum){
  if(window.BXHCourtRetirement&&!window.BXHCourtRetirement.accepts(st,stationNum))return [];
  if(!window.BXHCourtRetirement?.movableQueuedMatches)return [];
  const movable=new Set(window.BXHCourtRetirement.movableQueuedMatches(st).map(m=>m.id));
  const courts=st.courtAssignments||{};
  const busy=new Set(Object.values(courts).map(c=>c&&c.currentMatchId).filter(Boolean));
  const phase=(st.meta.formatType||"single")==="single"?activeSingleElimSchedulePhase(st.matches,st.meta):null;
  return (st.matches||[]).filter(m=>m&&movable.has(m.id)&&Number(m.station)!==Number(stationNum)&&!busy.has(m.id)&&
    !m.isBye&&!m.completed&&m.a&&m.b&&!m.skippedAt&&!m.callPass&&
    !matchHasDecisionData(m)&&["pending","ready"].includes(m.status||"pending")&&
    (!phase||isInActiveSingleElimPhase(m,phase,st.matches)||!singleElimBronzeBeforeFinalBlocked(m,st.matches,st.meta)))
    .sort((a,b)=>Number(a.seq||0)-Number(b.seq||0));
}

function isInActiveSingleElimPhase(match, phase, matches=state.matches){
  if(!phase) return true;
  if(phase.kind==="bronze") return match.bracket==="BZ" && match.id===phase.matchId;
  if(phase.kind==="bronze-pending") return false;
  return match.bracket==="SE" && Number(match.round||0)===phase.round && singleElimScheduleTier(match,matches)===phase.tier;
}

function markMatchSkipped(matchId){
  const m=getMatch(matchId);
  const queue=stationExecutionQueue(m.station);
  m.skipWaitFor=queue.filter(x=>x.id!==matchId&&!x.skippedAt).slice(0,2).map(x=>x.id);
  m.skipManualOnly=m.skipWaitFor.length===0;
  m.status="pending"; m.skippedAt=Date.now(); m.resumeQueuedAt=null;
  m.dispatchRevision=Number(m.dispatchRevision||0)+1;
  m.updatedAt=Date.now();
  Object.values(state.courtAssignments||{}).forEach(c=>{if(c.currentMatchId===matchId)c.currentMatchId=null;});
  rebuildCourtAssignments();
}

function matchesInRound(r){ return state.matches.filter(m=>m.round===r && (m.bracket==null || m.bracket==="SE")).sort((a,b)=>a.indexInRound-b.indexInRound); }

function matchesInRoundBracket(bracket, r){ return state.matches.filter(m=>m.bracket===bracket && m.round===r).sort((a,b)=>a.indexInRound-b.indexInRound); }

function normalizeHunterRoundEvent(raw,index,matchId){
  if(!raw || (raw.side!=="A" && raw.side!=="B")) return null;
  const type=String(raw.type||"");
  if(Number(raw.v)===2){
    if(raw.enchantment!==true)return null;
    const api=window.BXHEnchantmentScore;
    if(!api||!Number.isInteger(raw.round)||raw.round<1) return null;
    const computed=type==="fault"
      ? {ok:true,originalPoints:1,points:1,delta:0,appliedCardId:null}
      : api.resolve({type,winnerCardId:raw.winningCardId,loserCardId:raw.losingCardId});
    if(!computed.ok||Number(raw.basePoints)!==computed.originalPoints||
       Number(raw.points)!==computed.points||Number(raw.delta)!==computed.delta||
       (raw.appliedCardId||null)!==(computed.appliedCardId||null)) return null;
    if(type==="fault" && (raw.appliedCardId!=null||
       !api.CARDS[raw.winningCardId]||!api.CARDS[raw.losingCardId])) return null;
    if(!raw.eventId||Number(raw.seq)!==index+1)return null;
    return {v:2,eventId:String(raw.eventId),seq:index+1,round:raw.round,
      side:raw.side,type,basePoints:computed.originalPoints,points:computed.points,
      delta:computed.delta,appliedCardId:computed.appliedCardId,
      winningCardId:raw.winningCardId,losingCardId:raw.losingCardId,t:Number(raw.t)||null};
  }
  if(!HUNTER_VALID_POINT_TYPES.has(type)) return null;
  const expected=Number(POINT_TYPES[type]);
  const points=Number(raw.points);
  if(!Number.isFinite(points) || points!==expected) return null;
  const seq=Number.isInteger(Number(raw.seq))&&Number(raw.seq)>0?Number(raw.seq):index+1;
  const ts=Number(raw.t)||null;
  return {
    v:Number(raw.v)||HUNTER_ROUND_SCHEMA_VERSION,
    eventId:String(raw.eventId||((matchId||"match")+":legacy:"+seq)),
    seq,
    side:raw.side,
    type,
    points,
    t:ts
  };
}

function numRoundsTotal(){ return state.bracketSize ? Math.log2(state.bracketSize) : 0; }

function orderedMatches(){ return state.matches.slice().sort((x,y)=> (x.seq!=null&&y.seq!=null) ? x.seq-y.seq : (x.round-y.round || x.indexInRound-y.indexInRound)); }

function rebuildCourtAssignments(){
  window.BXHCourtRetirement?.reconcile(state);
  const n = Math.max(1, state.meta.stations||1);
  const existing = state.courtAssignments || {};
  const next = {};
  for(let i=1;i<=n;i++){
    const key = courtKey(i);
    next[key] = existing[key] ? Object.assign({}, existing[key]) : { currentMatchId:null, nextMatchId:null, status:"idle", lockedBy:null, lockedAt:null, updatedAt:null };
  }
  state.courtAssignments = next;

  for(let i=1;i<=n;i++){
    const key = courtKey(i);
    const court = state.courtAssignments[key];
    if(state.forcedCourtExits?.[i]?.closed){Object.assign(court,{currentMatchId:null,nextMatchId:null,status:"retired",lockedBy:null,lockedAt:null});continue;}
    const queue = stationExecutionQueue(i);

    let current = court.currentMatchId ? getMatch(court.currentMatchId) : null;
    // Drop the current assignment if it completed, or (due to a station
    // redistribution) no longer actually belongs to this court.
    if(current && (current.completed || current.station!==i)) current = null;
    if(current && singleElimBronzeBeforeFinalBlocked(current,state.matches,state.meta) && !matchHasDecisionData(current)){
      current.status="pending";current.startedAt=null;court.currentMatchId=null;current=null;
    }
    // A paused match STAYS as the court's current match (paused ≠ vacated).
    if(!current){
      const first=queue[0];
      const explicit=first&&(first.dispatchPriorityAt||first.resumeQueuedAt||first.skippedAt);
      current = (explicit?first:queue.find(m=>m.id===court.nextMatchId)||first) || null;
      court.currentMatchId = current ? current.id : null;
      if(current){
        ensureMatchStatusFields(current);
        if(state.startedAt){
          current.status = "in_progress";
          if(!current.startedAt) current.startedAt = Date.now();
          current.updatedAt = Date.now();
          current.dispatchPriorityAt = null;
          current.skippedAt = null; current.resumeQueuedAt=null; current.skipWaitFor=[]; current.skipManualOnly=false;
        }else{
          // 產生對戰表／預排裁判台不等於開賽。未按「開始賽事」前只能保持預備狀態。
          if(current.status==="pending") current.status="ready";
          current.startedAt = null;
        }
      }
    }
    // Preassigned first matches must become live when the tournament starts.
    if(current && state.startedAt && ["pending","ready"].includes(current.status)){
      current.status="in_progress";current.startedAt=current.startedAt||Date.now();current.updatedAt=Date.now();
    }
    const remaining = queue.filter(m=>m.id!==court.currentMatchId);
    // Preserve a displayed next (possibly notified), except for an explicit
    // swap/transfer/resume or the existing PASS dependency priority.
    const first=remaining[0];
    const explicit=first&&(first.dispatchPriorityAt||first.resumeQueuedAt||first.skippedAt);
    const nextM = (explicit?first:remaining.find(m=>m.id===court.nextMatchId)||first) || null;
    court.nextMatchId = nextM ? nextM.id : null;
    court.status = current ? (current.status||"in_progress") : "idle";
    court.updatedAt = Date.now();
  }
}

function rebuildPropagation(){
  const fmt = state.meta.formatType || "single";
  if(fmt==="double") rebuildPropagationDouble();
  else if(fmt==="roundrobin") rebuildPropagationRoundRobin();
  else rebuildPropagationSingle();
  syncMatchStatuses();
  rebuildCourtAssignments();
}

function rebuildPropagationDouble(){
  const k = numRoundsTotal();
  for(let r=1;r<k;r++){
    matchesInRoundBracket("WB", r).forEach(m=>{
      if(m.completed) return;
      const lower = matchesInRoundBracket("WB", r-1);
      const srcA = lower[m.indexInRound*2];
      const srcB = lower[m.indexInRound*2+1];
      const newA = srcA && srcA.winnerId ? srcA.winnerId : null;
      const newB = srcB && srcB.winnerId ? srcB.winnerId : null;
      applyPropagatedSlots(m, newA, newB);
    });
  }

  const de=window.BXHDoubleElim;
  const lbMatches = state.matches.filter(m=>m.bracket==="LB").sort((a,b)=> a.round-b.round || a.indexInRound-b.indexInRound);
  lbMatches.forEach(m=>{
    if(m.completed) return;
    const inputs=de ? de.sourceInputs(state.matches,m) : [{status:"pending"},{status:"pending"}];
    const newA=inputs[0]&&inputs[0].status==="player"?inputs[0].playerId:null;
    const newB=inputs[1]&&inputs[1].status==="player"?inputs[1].playerId:null;
    applyPropagatedSlots(m,newA,newB);
    const action=de ? de.classifyInputs(inputs) : "waiting";
    if(action==="void"){
      m.a=null;m.b=null;m.isBye=true;m.structuralVoid=true;m.completed=true;
      m.winnerId=null;m.loserId=null;
    }else if(action==="bye"){
      const winnerId=newA||newB;
      m.isBye=true;m.structuralVoid=false;m.completed=true;
      m.winnerId=winnerId;m.loserId=null;
    }else{
      m.isBye=false;m.structuralVoid=false;
    }
  });

  const gf = state.gfMatchId ? getMatch(state.gfMatchId) : null;
  if(gf){
    const wbFinal = getMatch(gf.gfSrc.wbFinalId);
    const lbFinal = gf.gfSrc.lbFinalId ? getMatch(gf.gfSrc.lbFinalId) : null;
    const newA = wbFinal && wbFinal.completed && wbFinal.winnerId ? wbFinal.winnerId : null;
    const newB = lbFinal && lbFinal.completed && lbFinal.winnerId ? lbFinal.winnerId : null;
    if(!gf.completed) applyPropagatedSlots(gf, newA, newB);
  }

  if(gf && gf.completed && gf.winnerId){
    const wbFinal = getMatch(gf.gfSrc.wbFinalId);
    const wbChampionId = wbFinal ? wbFinal.winnerId : null;
    if(gf.winnerId === wbChampionId){
      state.championId = gf.winnerId;
      state.runnerUpId = gf.loserId;
      if(state.gfResetMatchId){
        state.matches = state.matches.filter(mm=>mm.id!==state.gfResetMatchId);
        state.gfResetMatchId=null;
      }
    } else {
      if(!state.gfResetMatchId){
        const maxSeq = state.matches.reduce((mx,x)=> Math.max(mx, x.seq||0), 0);
        const resetM = { id:uid("m"), seq:maxSeq+1, bracket:"GFR", round:0, indexInRound:0,
          a:{type:"player",playerId:gf.a.playerId}, b:{type:"player",playerId:gf.b.playerId},
          isBye:false, scoreA:0,scoreB:0, log:[], winnerId:null, loserId:null, completed:false, station: gf.station };
        state.matches.push(resetM);
        state.gfResetMatchId = resetM.id;
      } else {
        const resetM = getMatch(state.gfResetMatchId);
        if(resetM && !resetM.completed){
          resetM.a = {type:"player",playerId:gf.a.playerId};
          resetM.b = {type:"player",playerId:gf.b.playerId};
        }
      }
      const resetM = getMatch(state.gfResetMatchId);
      if(resetM && resetM.completed && resetM.winnerId){
        state.championId = resetM.winnerId;
        state.runnerUpId = resetM.loserId;
      } else {
        state.championId = null; state.runnerUpId = null;
      }
    }
  } else {
    state.championId = null; state.runnerUpId = null;
    if(state.gfResetMatchId){
      state.matches = state.matches.filter(mm=>mm.id!==state.gfResetMatchId);
      state.gfResetMatchId=null;
    }
  }

  const placement=de?de.placements(state.matches,state.gfMatchId):{thirdId:null,fourthId:null};
  state.thirdId=placement.thirdId;
  state.fourthId=placement.fourthId;
}

function rebuildPropagationForState(targetState){
  if(!targetState) return targetState;
  const previousState=state;
  try{
    state=targetState;
    rebuildPropagation();
    // Only the authoritative transaction may rebalance queued matches. Never
    // move a match currently displayed on another court or one with play data.
    if(state.startedAt&&state.archiveStatus!=="completed"){
      let moved=false;
      for(let n=1;n<=Math.max(1,Number(state.meta.stations)||1);n++){
        const court=state.courtAssignments[courtKey(n)];
        if(court&&!court.currentMatchId){
          const candidate=idleCourtCandidates(state,n)[0];
          if(candidate&&applyIdleCourtClaim(state,candidate.id,n).ok)moved=true;
        }
      }
      if(moved)rebuildPropagation();
    }
    return targetState;
  }finally{
    state=previousState;
  }
}

function rebuildPropagationRoundRobin(){
  const real = state.matches.filter(m=>m.bracket==="RR");
  const allDone = real.length>0 && real.every(m=>m.completed);
  if(!allDone){ state.championId=null; state.runnerUpId=null; state.thirdId=null; state.fourthId=null; return; }
  const standings = computeRoundRobinStandings();
  state.championId = standings[0] && !standings[0].tied ? standings[0].id : null;
  state.runnerUpId = standings[1] && !standings[1].tied ? standings[1].id : null;
  state.thirdId = standings[2] && !standings[2].tied ? standings[2].id : null;
  state.fourthId = standings[3] && !standings[3].tied ? standings[3].id : null;
}

function rebuildPropagationSingle(){
  const total = numRoundsTotal();
  for(let r=1;r<total;r++){
    matchesInRound(r).forEach(m=>{
      const lower = matchesInRound(r-1);
      const srcA = lower[m.indexInRound*2];
      const srcB = lower[m.indexInRound*2+1];
      const newA = srcA && srcA.winnerId ? srcA.winnerId : null;
      const newB = srcB && srcB.winnerId ? srcB.winnerId : null;
      applyPropagatedSlots(m, newA, newB);
    });
  }
  const finalRound = total-1;
  const finalMatches = matchesInRound(finalRound);
  if(finalMatches.length===1 && finalMatches[0].completed && finalMatches[0].winnerId){
    state.championId = finalMatches[0].winnerId;
    state.runnerUpId = finalMatches[0].loserId || null;
  } else {
    state.championId = null; state.runnerUpId = null;
  }

  // bronze match (3rd place) — additive, optional, must live in state.matches so the referee can play it
  state.bronzeMatchId = state.bronzeMatchId || null;
  if(state.meta.bronzeMatch && total>=2){
    const semis = matchesInRound(total-2).filter(m=>!m.isBye);
    if(semis.length===2 && semis[0].completed && semis[1].completed){
      const loserA = semis[0].loserId, loserB = semis[1].loserId;
      if(loserA && loserB){
        const finalMatch=matchesInRound(total-1)[0]||null;
        const finalSeq=Number(finalMatch&&finalMatch.seq);
        const semiMaxSeq=Math.max(...semis.map(m=>Number(m.seq)||0));
        const bronzeSeq=Number.isFinite(finalSeq)?finalSeq-0.5:semiMaxSeq+0.5;
        let bronze = state.bronzeMatchId ? getMatch(state.bronzeMatchId) : null;
        if(!bronze){
          bronze = { id: uid("bz"), seq:bronzeSeq, bracket:"BZ", round:total-2, indexInRound:0, isBye:false, scoreA:0,scoreB:0, log:[], winnerId:null, loserId:null, completed:false, station: semis[0].station };
          state.matches.push(bronze);
          state.bronzeMatchId = bronze.id;
        }
        bronze.seq=bronzeSeq;
        const curA = bronze.a?bronze.a.playerId:null, curB = bronze.b?bronze.b.playerId:null;
        if(curA!==loserA || curB!==loserB){
          bronze.a={type:"player",playerId:loserA}; bronze.b={type:"player",playerId:loserB};
          bronze.scoreA=0;bronze.scoreB=0;bronze.log=[];bronze.faultActions=[];bronze.winnerId=null;bronze.loserId=null;bronze.completed=false;
        }
      }
    }
    const bronzeNow = state.bronzeMatchId ? getMatch(state.bronzeMatchId) : null;
    if(bronzeNow && bronzeNow.completed){
      state.thirdId = bronzeNow.winnerId;
      state.fourthId = bronzeNow.loserId;
    } else {
      state.thirdId = null; state.fourthId = null;
    }
  } else {
    if(state.bronzeMatchId){
      state.matches = state.matches.filter(mm=>mm.id!==state.bronzeMatchId);
      state.bronzeMatchId = null;
    }
    state.thirdId = null; state.fourthId = null;
  }

  // Three-player single elimination is a special, valid BYE bracket:
  // one player receives the BYE, the other two play the semifinal/play-in,
  // and that first real match loser is the sole third-place finisher.
  // Do this in the authoritative propagation layer so archive, history,
  // celebration and cloud snapshots all receive the same placement.
  const eligibleThree=tournamentEligiblePlayers(state.players,state.meta,state.matches);
  if(eligibleThree.length===3 && state.championId && state.runnerUpId){
    const remaining=eligibleThree.filter(p=>p&&p.id!==state.championId&&p.id!==state.runnerUpId);
    if(remaining.length===1){
      state.thirdId=remaining[0].id;
      state.fourthId=null;
    }
  }
}

function refereeMatches(){ return orderedMatches().filter(m=>!m.isBye); }

function resolveScoringModeForRound(bracket, round){
  // New matches always record every scoring round. Existing match modes remain
  // intact for legacy results and server-authoritative matches already created.
  return "standard";
}

function singleElimBronzeBeforeFinalBlocked(match,matches=state.matches,meta=state.meta){
  if(!match||match.bracket!=="SE") return false;
  const gate=singleElimBronzeGatePhase(matches,meta);
  if(!gate) return false;
  return Number(match.round||0)===Number(gate.finalRound);
}

function singleElimBronzeGatePhase(matches=state.matches, meta=state.meta){
  if((meta&&meta.formatType||"single")!=="single" || !(meta&&meta.bronzeMatch)) return null;
  const se=matches.filter(m=>m&&m.bracket==="SE"&&!m.isBye);
  if(!se.length) return null;
  const finalRound=Math.max(...se.map(m=>Number(m.round)||0));
  if(finalRound<1) return null;
  const semis=se.filter(m=>Number(m.round||0)===finalRound-1);
  const losersReady=semis.length===2&&semis.every(m=>m.completed&&m.loserId);
  if(!losersReady) return null;
  const bronze=matches.find(m=>m&&m.bracket==="BZ"&&!m.isBye);
  if(bronze&&bronze.completed) return null;
  if(bronze&&bronze.a&&bronze.b) return {kind:"bronze",matchId:bronze.id,finalRound};
  // Defensive hold: semifinal losers are already known but the BZ node has not
  // been materialized yet. Never let the championship final slip through this
  // transient propagation window.
  return {kind:"bronze-pending",matchId:bronze&&bronze.id||null,finalRound};
}

function singleElimScheduleTier(match, matches=state.matches){
  if(!match || match.bracket!=="SE" || Number(match.round||0)===0) return 0;
  const feederRound=Number(match.round)-1;
  const feederStart=Number(match.indexInRound||0)*2;
  let playedFeeders=0;
  for(let i=0;i<2;i++){
    const feeder=matches.find(x=>x.bracket==="SE" && Number(x.round)===feederRound && Number(x.indexInRound)===feederStart+i);
    if(feeder && !feeder.isBye) playedFeeders++;
  }
  return playedFeeders;
}

function stationExecutionQueue(stationNum){
  if(state.forcedCourtExits?.[stationNum]?.closed)return [];
  const retirement=state.courtRetirementPlan?.courts?.[stationNum];
  if(retirement&&Number(stationNum)>window.BXHCourtRetirement.target(state))return refereeMatches().filter(m=>Number(m.station)===Number(stationNum)&&!m.completed&&retirement.holdIds.includes(m.id)&&m.a&&m.b&&!m.skippedAt);
  let available=refereeMatches().filter(m=>m.station===stationNum&&!m.completed&&m.a&&m.b&&m.status!=="paused");
  if((state.meta.formatType||"single")==="single"){
    const phase=activeSingleElimSchedulePhase();
    if(phase){
      // Preserve normal independent per-court progression, but never permit the
      // championship final to bypass a pending 季殿 placement match.
      const samePhase=available.filter(m=>isInActiveSingleElimPhase(m,phase));
      const laterReady=available.filter(m=>!isInActiveSingleElimPhase(m,phase));
      available=samePhase.concat(laterReady.filter(m=>!singleElimBronzeBeforeFinalBlocked(m)));
    }
  }
  const normal=available.filter(m=>!m.skippedAt).sort((a,b)=>{
    const ap=Number(a.dispatchPriorityAt||0),bp=Number(b.dispatchPriorityAt||0);
    if(!!ap!==!!bp) return ap?-1:1;
    if(ap&&bp&&ap!==bp) return bp-ap;
    return Number(a.seq||0)-Number(b.seq||0);
  });
  const skipped=available.filter(m=>m.skippedAt&&!m.resumeQueuedAt&&!m.skipManualOnly).sort((a,b)=>a.skippedAt-b.skippedAt || String(a.id).localeCompare(String(b.id)));
  for(const m of skipped){
    if(!Array.isArray(m.skipWaitFor)) m.skipWaitFor=normal.slice(0,2).map(x=>x.id); // legacy rooms
  }
  const result=normal.slice();
  for(const m of skipped.slice().reverse()){
    const at=result.reduce((last,x,i)=>m.skipWaitFor.includes(x.id)?i+1:last,0);
    if(m.callPass && m.callPass.waitFor.some(id=>!getMatch(id)?.completed && !result.some(x=>x.id===id)))continue;
    result.splice(at,0,m);
  }
  const claimed=available.filter(m=>m.skippedAt&&m.resumeQueuedAt).sort((a,b)=>a.resumeQueuedAt-b.resumeQueuedAt || String(a.id).localeCompare(String(b.id)));
  return claimed.concat(result);
}

function syncMatchStatuses(){
  if(!state.meta.scoringMode) state.meta.scoringMode = "standard";
  if(!state.meta.roundScoringModes) state.meta.roundScoringModes = {};
  state.matches.forEach(m=>{
    ensureMatchStatusFields(m);
    ensureMatchScoringFields(m);
    if(m.isBye){
      if(m.status!=="completed"){ m.status = "completed"; if(!m.completedAt) m.completedAt = m.completedAt || Date.now(); }
      return;
    }
    if(m.completed && m.status!=="completed"){
      m.status = "completed";
      if(!m.completedAt) m.completedAt = Date.now();
    }
  });
  autoAdvanceReadyMatches();
}

function tournamentEligiblePlayers(players,meta,matches){
  const list=Array.isArray(players)?players.filter(Boolean):[];
  const needsCheckin=!!(meta&&meta.checkinRequired);
  if(!needsCheckin) return list;

  const checked=list.filter(p=>p.checkedIn===true);
  if(checked.length || !Array.isArray(matches) || !matches.length) return checked;

  // Historical/legacy fallback: once a check-in-required bracket exists, the
  // bracket itself is authoritative for who actually entered the tournament.
  const bracketIds=new Set();
  matches.forEach(m=>{
    if(m&&m.a&&m.a.playerId) bracketIds.add(m.a.playerId);
    if(m&&m.b&&m.b.playerId) bracketIds.add(m.b.playerId);
  });
  return bracketIds.size ? list.filter(p=>bracketIds.has(p.id)) : checked;
}

function validateHunterRoundLedger(match){
  const raw=Array.isArray(match&&match.log)?match.log:[];
  const events=[];
  const errors=[];
  raw.forEach((row,index)=>{
    const normalized=normalizeHunterRoundEvent(row,index,match&&match.id);
    if(normalized) events.push(normalized);
    else errors.push({index,reason:"invalid-round-event"});
  });
  const scoreA=events.filter(e=>e.side==="A").reduce((sum,e)=>sum+e.points,0);
  const scoreB=events.filter(e=>e.side==="B").reduce((sum,e)=>sum+e.points,0);
  const expectedA=Number(match&&match.scoreA);
  const expectedB=Number(match&&match.scoreB);
  if(!Number.isFinite(expectedA)||!Number.isFinite(expectedB)) errors.push({reason:"invalid-match-score"});
  else if(scoreA!==expectedA||scoreB!==expectedB) errors.push({reason:"score-ledger-mismatch",scoreA,scoreB,expectedA,expectedB});
  return {ok:errors.length===0,events,roundCount:events.length,scoreA,scoreB,errors};
}
